window.ScripturaLexicons.BDAG_PART_0263 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-01\" data-source=\"BDAG\" data-search=\"ὀφείλω verbo dever; estar obrigado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφείλω</td><td>verbo</td><td>dever; estar obrigado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-02\" data-source=\"BDAG\" data-search=\"ὄφελον partícula desiderativa oxalá; quem dera BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄφελον</td><td>partícula desiderativa</td><td>oxalá; quem dera</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-03\" data-source=\"BDAG\" data-search=\"ὄφελος, ους, τό substantivo neutro proveito; benefício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄφελος, ους, τό</td><td>substantivo neutro</td><td>proveito; benefício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-04\" data-source=\"BDAG\" data-search=\"ὀφθαλμοδουλία, ας, ἡ substantivo feminino serviço de aparência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφθαλμοδουλία, ας, ἡ</td><td>substantivo feminino</td><td>serviço de aparência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-05\" data-source=\"BDAG\" data-search=\"ὀφθαλμός, οῦ, ὁ substantivo masculino olho; entendimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφθαλμός, οῦ, ὁ</td><td>substantivo masculino</td><td>olho; entendimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-06\" data-source=\"BDAG\" data-search=\"ὀφθείς, ὀφθήσομαι formas verbais ver ὁράω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφθείς, ὀφθήσομαι</td><td>formas verbais</td><td>ver ὁράω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-07\" data-source=\"BDAG\" data-search=\"ὄφις, εως, ὁ substantivo masculino cobra; serpente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄφις, εως, ὁ</td><td>substantivo masculino</td><td>cobra; serpente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-08\" data-source=\"BDAG\" data-search=\"ὀφλισκάνω verbo incorrer em culpa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφλισκάνω</td><td>verbo</td><td>incorrer em culpa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-09\" data-source=\"BDAG\" data-search=\"ὀφρῦς substantivo feminino sobrancelha; borda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀφρῦς</td><td>substantivo feminino</td><td>sobrancelha; borda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-10\" data-source=\"BDAG\" data-search=\"ὀχετός, οῦ, ὁ substantivo masculino canal; esgoto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀχετός, οῦ, ὁ</td><td>substantivo masculino</td><td>canal; esgoto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-11\" data-source=\"BDAG\" data-search=\"ὀχλέω verbo perturbar; afligir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀχλέω</td><td>verbo</td><td>perturbar; afligir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-12\" data-source=\"BDAG\" data-search=\"ὀχλοποιέω verbo formar uma turba BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀχλοποιέω</td><td>verbo</td><td>formar uma turba</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-13\" data-source=\"BDAG\" data-search=\"ὄχλος, ου, ὁ substantivo masculino multidão; povo; massas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄχλος, ου, ὁ</td><td>substantivo masculino</td><td>multidão; povo; massas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-14\" data-source=\"BDAG\" data-search=\"Ὀχοζίας, ου, ὁ nome próprio masculino Acazias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ὀχοζίας, ου, ὁ</td><td>nome próprio masculino</td><td>Acazias</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-15\" data-source=\"BDAG\" data-search=\"ὀχυρός, ά, όν adjetivo forte; firme BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀχυρός, ά, όν</td><td>adjetivo</td><td>forte; firme</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-16\" data-source=\"BDAG\" data-search=\"ὀχύρωμα, ατος, τό substantivo neutro fortaleza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀχύρωμα, ατος, τό</td><td>substantivo neutro</td><td>fortaleza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-17\" data-source=\"BDAG\" data-search=\"ὀψάριον, ου, τό substantivo neutro peixe; petisco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀψάριον, ου, τό</td><td>substantivo neutro</td><td>peixe; petisco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-18\" data-source=\"BDAG\" data-search=\"ὀψέ advérbio tarde; depois de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀψέ</td><td>advérbio</td><td>tarde; depois de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-19\" data-source=\"BDAG\" data-search=\"ὀψία, ας, ἡ substantivo feminino ver ὄψιος 2 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀψία, ας, ἡ</td><td>substantivo feminino</td><td>ver ὄψιος 2</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0263-20\" data-source=\"BDAG\" data-search=\"ὄψιμος, ον adjetivo tardio; chuva da primavera BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄψιμος, ον</td><td>adjetivo</td><td>tardio; chuva da primavera</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0263-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφείλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφείλω</span>, imperfeito <span class=\"greek\">ὤφειλον</span>; futuro <span class=\"greek\">ὀφειλήσω</span> na LXX; nossa literatura apresenta apenas o presente e o imperfeito (Homero e posteriores).<br>\n① Estar em dívida com alguém no sentido financeiro, dever alguma coisa a alguém, estar endividado; com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:28a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:5</a>. Com acusativo da dívida (Appian, Bell. Civ. 2, 8 §26; Jos., Ant. 13, 56), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:28b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:41</a>; 16:7; Phlm 18 (CMartin, em Persuasive Artistry, org. DWatson, ’91, 321–37). <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀφειλόμενον</span>, a quantia devida (X.; Pla.; CPR I, 228, 5. Nos papiros, o plural é mais frequente nessa acepção), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:30</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">αὐτῷ</span>, a quantia total que lhe devia, v. 34.<br>\n② Estar sujeito à obrigação de corresponder a determinadas expectativas sociais ou morais, dever.<br>\nⓐ Em sentido geral.<br>\n<span class=\"greek\">α</span>. Dever, estar em dívida com <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, com alguém por alguma coisa (Alciphron 4, 13, 1 <span class=\"greek\">Νύμφαις</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">ὀφ</span>.; Jos., C. Ap. 2, 295): <span class=\"greek\">πόσα</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ὀφείλομεν</span> <span class=\"greek\">ὅσια</span>; «Por quantas ações santas estamos em dívida com (Jesus Cristo)?», 2 Cl 1:3. <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὀφείλετε</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">ἀγαπᾶν</span>, «Não devais nada a ninguém, a não ser amar uns aos outros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:8</a> (AFridrichsen, StKr 102, 1930, 294–97. Sobre a iniciativa na bondade, cf. Thu. 2, 40: «Conquistamos amigos não por receber benefícios, mas por concedê-los»). <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀφειλομένην</span> <span class=\"greek\">εὔνοιαν</span>, a benevolência devida, eufemismo para agradar conjugalmente ao cônjuge, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:3</a>, variante textual. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀφειλόμενον</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span>, «Ao glorioso lugar que merecia», 1 Cl 5:4. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀφειλόμενον</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">εἰσὶ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>, Pol 9:2.—Substantivado: <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀφειλόμενα</span> (ver 1 acima), deveres, obrigações; <span class=\"greek\">ποιεῖν</span>, cumprir, GPt 12:53.<br>\n<span class=\"greek\">β</span>. Estar obrigado; seguido de infinitivo: deve-se, é necessário, convém (Hom. [Il. 19, 200] e outros; inscrições, papiros; 4 Macc 11:15; 16:19; Philo, Agr. 164, Spec. Leg. 1, 101; TestJos 14:6; Just., A I, 4, 4 e outros; Mel., P. 76, 550; Iren., Did.): <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ὠφείλομεν</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">πεποιήκαμεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:10</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νόμον</span> <span class=\"greek\">ὀφείλει</span> <span class=\"greek\">ἀποθανεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:7</a>. Cf. 13:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:1</a>, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:36</a>; 9:10; 11:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:3</a>; 2:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a>; 5:3, 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:6</a>; 3:16; 4:11; 3J 8; 1 Cl 38:4; 40:1; 48:6; 51:1; 2 Cl 4:3; B 1:7; 2:1, 9f; 4:6; 5:3; 6:18; 7:1, 11; 13:3; Pol 5:1; 6:2; Hs 8, 9, 4, variante textual; 9, 13, 3; 9, 18, 2; 9, 28, 5. Na negativa, não se deve, não é permitido (Jos., Vi. 149; Ar. 13, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:7</a>; 1 Cl 56:2; Hm 4, 1, 3; 8; Hs 5, 4, 2; 9, 18, 1. Cf. 2 Cl 4:3. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀφείλει</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γονεῦσι</span> <span class=\"greek\">θησαύριζειν</span>, «Os filhos não têm obrigação de acumular dinheiro para os pais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:14</a>.<br>\nⓑ O uso rabínico deu origem a certas particularidades.<br>\n<span class=\"greek\">α</span>. <span class=\"greek\">ὀφ</span>. empregado absolutamente [<span class=\"hebrew\" dir=\"rtl\">חַיָּב</span>]: <span class=\"greek\">ὀφείλει</span>, «Está obrigado, vinculado (por seu juramento)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:16</a>, 18.<br>\n<span class=\"greek\">β</span>. Cometer um pecado (ver <span class=\"greek\">ὀφείλημα</span> 2; mas cf. também SIG 1042, 15 <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">ὀφιλέτω</span> <span class=\"greek\">Μηνὶ</span> <span class=\"greek\">Τυράννῳ</span>); com dativo, contra alguém: <span class=\"greek\">ἀφίομεν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">ὀφείλοντι</span> <span class=\"greek\">ἡμῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:4</a>.<br>\n③ Ser compelido pelas circunstâncias (melhor traduzido com um verbo auxiliar), ter de, dever: <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">ὠφείλετε</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">ἐξελθεῖν</span>, «Nesse caso, teríeis de sair inteiramente do mundo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:10</a>.—<span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὤφειλον</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">συνίστασθαι</span>, «Eu deveria ter sido recomendado por vós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:11</a> (B-D-F §358, 1; Rob. 920). Sobre a perspectiva semântica em que Paulo figura como credor, não como devedor, cf. o emprego de <span class=\"greek\">ὀφείλημα</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:4</a>. O uso elaborado, por Paulo, de linguagem corrente nos discursos de reciprocidade condiz com o contexto, em que a ironia desempenha papel decisivo.—B. 641. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄφελον</h1><div class=\"entry-meta\"><span>partícula desiderativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄφελον</span> (provavelmente não é a primeira pessoa do 2.º aoristo de <span class=\"greek\">ὀφείλω</span> [<span class=\"greek\">ὤφελον</span>] sem aumento [como entendem a maioria dos estudiosos, inclusive Mlt. 201, nota 1; Mlt-H. 191], mas uma partícula, originalmente com <span class=\"greek\">ἐστίν</span> subentendido [JWackernagel, Sprachl. Untersuchungen. zu Homer 1916, 199f; B-D-F §67, 2; assim também L-S-J-M s.v. <span class=\"greek\">ὀφείλω</span>, final]; <span class=\"greek\">ὄφελον</span>: OGI 315, 16 [164/163 a.C.]; Epict. 2, 18, 15, variante textual, Sch.; 2, 22, 12, como correção no manuscrito S; LXX; En 104:11). Forma fixa que funciona como partícula introdutora de desejos irrealizáveis (B-D-F §359, 1; Rob. 1003f), expressão do desejo de que algo tivesse acontecido ou viesse a acontecer, oxalá, quem dera. Com imperfeito para exprimir tempo presente (Epict. 2, 22, 12; Dio Chrys. 21 [38], 47 vArnim [a edição Budé traz <span class=\"greek\">ὤφελον</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:15</a> (Schwyzer II 346); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:1</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ὄφελον</span> <span class=\"greek\">ἐμιμοῦντο</span>, ISm 12:1. Com optativo (Ps 118:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:15</a>, variante textual (leitura erasmiana).—Com aoristo do indicativo para exprimir tempo passado (Epict. 2, 18, 15; Chariton 4, 4, 2; Achilles Tat. 2, 24, 3; 5, 15, 5; Ex 16:3; Num 14:2; 20:3): <span class=\"greek\">ὄφελόν</span> <span class=\"greek\">γε</span> <span class=\"greek\">ἐβασιλεύσατε</span>, «De fato, quem dera tivésseis chegado a reinar!», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:8</a>.—Com futuro do indicativo (segundo Lucian, Soloec. 1, final, <span class=\"greek\">ὄφελον</span> … <span class=\"greek\">δυνήσῃ</span> é um solecismo): <span class=\"greek\">ὄφ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀποκόψονται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:12</a> (ver <span class=\"greek\">ἀποκόπτω</span> a e B-D-F §384; Rob. 923).—DELG s.v. <span class=\"greek\">ὀφείλω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄφελος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄφελος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὀφέλλω</span>, «aumentar»; Hom. e posteriores; OGI 519, 26 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὄφελος</span> <span class=\"greek\">ἡμεῖν</span>; POxy 118, verso, 30 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὄφ</span>.; 1468, 6; Job 15:3; ApcSed 1, 3 [segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2</a>]; Jos., Ant. 17, 154; Just.; Ath. 22, 8), vantagem obtida de alguma coisa, benefício, proveito. <span class=\"greek\">τί</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄφ</span>.; «Que proveito há nisso?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:16</a> (Hierocles 14, 451; Philo, Migr. Abr. 55 e Just., D. 14, 1 <span class=\"greek\">τί</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὄφ</span>.;). Seguido de <span class=\"greek\">ἐάν</span> (cf. Ael. Aristid. 53 p. 640 D.; M. I. Brutus, Ep. 4), v. 14; 2 Cl 6:2 (dito de Jesus; em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:26</a> <span class=\"greek\">τί</span> <span class=\"greek\">ὠφεληθήσεται</span> <span class=\"greek\">ἄνθρωπος</span>, <span class=\"greek\">ἐὰν</span> … ;). <span class=\"greek\">τί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄφ</span>.; «De que me aproveita isso?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:32</a>. <span class=\"greek\">τί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὄφελος</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἑωρακότι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γινώσκοντι</span> … ; «Que proveito tenho em ter visto essas coisas e não as compreender?», Hv 3, 3, 1 (<span class=\"greek\">τί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὄφελος</span>; Chariton 7, 4, 10).—DELG s.v. 2 <span class=\"greek\">ὀφέλλω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφθαλμοδουλία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφθαλμοδουλία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (B-D-F §115, 1; ver também Mlt-H. 271; FGingrich, JBL 52, ’33, 263; Achmes p. 18, 12 diz acerca de um escravo <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὀφθαλμὸν</span> <span class=\"greek\">δουλεύειν</span>), serviço realizado somente para causar boa impressão na presença do senhor, serviço de aparência, serviço prestado apenas sob vigilância (CMoule, ET 59, ’47/48, 250), e não por mérito próprio, nem para agradar a Deus ou à própria consciência (ver Theodoret III p. 437 Schulze, acerca de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:6f</a>, <span class=\"greek\">ὀφθαλμοδουλείαν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καλεῖ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">εἰλικρινοῦς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">προσφερομένην</span> <span class=\"greek\">θεραπείαν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σχήματι</span> <span class=\"greek\">κεχρωσνένην</span> = ele aplica a expressão «serviço de aparência» àquele que não é prestado com sinceridade de coração, mas apenas para manter as aparências): <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὀφθαλμοδουλίαν</span>, «Somente quando o senhor está olhando», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:6</a>. No plural, indicando mais de uma ocorrência desse tipo de serviço: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοδουλίᾳ</span> (variante textual -<span class=\"greek\">λίαις</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:22</a>.—Ver DELG <span class=\"greek\">ὄπωπα</span> F 2. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφθαλμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφθαλμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores).<br>\n① Olho como órgão da percepção sensorial, olho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:29</a>, 38 (Ex 21:24; ver DDaube, JTS 45, ’44, 177–89.—O princípio <span class=\"greek\">ἐάν</span> <span class=\"greek\">τίς</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ὀφθαλμὸν</span> <span class=\"greek\">ἐκκόψῃ</span>, <span class=\"greek\">ἀντεκκόπτεσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐκείνου</span> na antiga legislação grega, em Diod S 12, 17, 4; Diog. L. 1, 57 [Solon]); 6:22; 7:3ff (ver <span class=\"greek\">δοκός</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:41f</a>; 11:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:16f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:14</a>; 2:18; 7:17; 19:12; 21:4; 1 Cl 10:4 (Gen 13:14) e frequentemente; GJs 19:2. Mais de dois olhos no mesmo ser (Artem. 1, 26 p. 28, 13ff), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:6</a>, 8 (segundo Ezk 1:18; 10:12); 5:6 (cf. Lucian, Dial. Deor. 3 e 20, 8: Argos, de muitos olhos, que enxerga com todo o corpo e nunca dorme; Ath. 20, 1 [referente a Atena]).—<span class=\"greek\">εἶδον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">μου</span> (cf. Sir 16:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:30</a>; cf. 4:20; 10:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:9</a> (=1 Cl 34:8; 2 Cl 11:7; MPol 2:3. Sobre possíveis associações gnósticas, ver UWilcken, Weisheit u. Torheit, ’59, 77–80 e Hippolytus 5, 26, 16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:7</a>.—<span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφ</span>., Dg 2:1 (Philo, Sacr. Abel. 24). <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἑωράκαμεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:1</a> (cf. Zech 9:8 A). <span class=\"greek\">βλέπειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφ</span>., GJs 17:2. <span class=\"greek\">ὀφ</span>. <span class=\"greek\">πονηρός</span>, «olho mau», isto é, um olhar que encara outras pessoas com inveja ou ciúme (Sir 14:10; Maximus Tyr. 20:7b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:23</a> (em oposição a <span class=\"greek\">ἁπλοῦς</span>; ver esse verbete, a literatura s.v. <span class=\"greek\">λύχνος</span> b e <span class=\"greek\">πονηρός</span> 3a, bem como PFiebig, Das Wort Jesu v. Auge: StKr 89, 1916, 499–507; CEdlund, Das Auge der Einfalt: ASNU 19, ’52; HCadbury, HTR 47, ’54, 69–74; JHElliott, The Evil Eye and the Sermon on the Mt: Biblical Interpretation 2, ’94, 51–84). Cf. 20:15. Por metonímia, inveja, malícia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:22</a> (mas o sentido «mesquinhez, amor aos próprios bens» é defendido para todas as ocorrências neotestamentárias de <span class=\"greek\">ὀφ</span>. <span class=\"greek\">πον</span>. por CCadoux, ET 53, ’41/42, 354f, especialmente para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:15</a>, com referência a Dt 15:9 e outras passagens. Inveja etc. são preferidas por CSmith, ibid. 181f; 54, ’42/43, 26 e JPercy, ibid. 26f).—<span class=\"greek\">ἐν</span> <span class=\"greek\">ῥιπῄ</span> <span class=\"greek\">ὀφθαλμοῦ</span>, «num piscar de olhos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.52\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:52</a>. <span class=\"greek\">ἀγαπήσεις</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κόρην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">σου</span>, «Amarás como a menina dos teus olhos», 19:9 (ver <span class=\"greek\">κόρη</span>).—Empregado com verbos: <span class=\"greek\">αἴρω</span> <span class=\"greek\">ἄνω</span> (<span class=\"greek\">αἴρω</span> 1b); <span class=\"greek\">ἀνοίγω</span> (ver este verbete, 5b); <span class=\"greek\">ἐξαιρέω</span> (ver este verbete, 1); <span class=\"greek\">ἐξορύσσω</span> (ver este verbete); <span class=\"greek\">ἐπαίρω</span> (ver este verbete, 1); <span class=\"greek\">κρατέω</span> (ver este verbete, 5); <span class=\"greek\">ὑπολαμβάνειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">τινός</span>, «Elevar alguém para fora do campo de visão de outra pessoa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:9</a>.—<span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιθυμία</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφθαλμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:16</a> (Maximus Tyr. 19, 21m: <span class=\"greek\">ἐπιθυμία</span> passa pelos <span class=\"greek\">ὀφθαλμοί</span>). <span class=\"greek\">ὀφθαλμοὶ</span> <span class=\"greek\">μεστοὶ</span> <span class=\"greek\">μοιχαλίδος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:14</a> (sobre a figura, cf. Sir 26:9; ver <span class=\"greek\">μεστός</span> 2b).—É característico do AT (mas ver também Hes., Op. 267 <span class=\"greek\">πάντα</span> <span class=\"greek\">ἰδὼν</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">ὀφθαλμός</span>; Polyb. 23, 10, 3 <span class=\"greek\">Δίκης</span> <span class=\"greek\">ὀφ</span>.; Aristaen, Ep. 1, 19, no início, o plural dos olhos de Tique. <span class=\"greek\">ὄμματα</span> também ocorre em referência a uma divindade: Alciphron 3, 8, 2; 4, 9, 4) falar antropomorficamente dos olhos de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:12</a>; 1 Cl 22:6 (as duas últimas ocorrências, Ps 33:16). A passagem da imagem para a acepção seguinte ocorre naturalmente:<br>\n② Compreensão mental e espiritual, olho, entendimento: <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">βλέπετε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:18</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:27b</a> (os três citam Is 6:10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:16</a>. <span class=\"greek\">ἔδωκεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλέπειν</span>, «Deus lhes deu olhos com os quais não enxergam» (ver B-D-F §393, 6; 400, 2; Rob. 1061; 1076), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:8</a> (cf. Dt 29:3). <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span>, «os olhos do coração» (ver <span class=\"greek\">καρδία</span> 1b<span class=\"greek\">β</span> e cf. Herm. Wr. 7, 1 <span class=\"greek\">ἀναβλέψαντες</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ὀφθαλμοῖς</span>; 10, 4 <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοῦ</span> <span class=\"greek\">ὀφθαλμός</span>; Just., D. 134, 5 <span class=\"greek\">οἱ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">ὀφθαλμοί</span>.—Sir 17:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:18</a>; 1 Cl 36:2; 59:3; MPol 2:3. Cf. também os verbetes <span class=\"greek\">καμμύω</span>, <span class=\"greek\">σκοτίζω</span>, <span class=\"greek\">τυφλόω</span>.—Com preposição: <span class=\"greek\">ἀπέναντι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφ</span>. <span class=\"greek\">τινος</span>, ver <span class=\"greek\">ἀπέναντι</span> 1b<span class=\"greek\">β</span>. <span class=\"greek\">ἐκρύβη</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">σου</span>, «Está oculto aos olhos da tua mente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:42</a> (cf. Sir 17:15). <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖς</span> (LXX; ver Thackeray 43): <span class=\"greek\">ἔστιν</span> <span class=\"greek\">θαυμαστὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖς</span> <span class=\"greek\">ἡμῶν</span>, «É maravilhoso aos nossos olhos (= em nosso julgamento)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:11</a> (ambos Ps 117:23); mas <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖς</span> <span class=\"greek\">ἡμῶν</span>, GJs 16:1 (como Lucian, Tox. 39), significa «Diante de nossos olhos» (assim também Apollon. Rhod. 4, 1619 <span class=\"greek\">τέρας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖσιν</span> <span class=\"greek\">ἰδόντες</span> = contemplar com os olhos o prodígio; Diod S 3, 18, 5 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖς</span> = diante de seus olhos). <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὀφθαλμούς</span> <span class=\"greek\">τινος</span>, «Diante dos olhos de alguém, à vista de alguém» (2 Km 12:11; 4 Km 25:7; Jer 35:5; Ezk 20:14, 22, 41; 21:11; 22:16; 36:23): <span class=\"greek\">οἷς</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">προεγράφη</span>, «Diante de cujos olhos Jesus Cristo foi apresentado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:1</a>. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ὀφθαλμῶν</span>, «Diante dos olhos (de alguém)» (Hyperid. 6, 17; SIG 495, 120 [c. 230 a.C.]; BGU 362 V, 8; LXX; EpArist 284): <span class=\"greek\">πρὸ</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">λαμβάνειν</span> (Polyb.; Diod S 26, 16b [ver FKrebs, Die Präp. bei Polyb. 1882, 38]; 2 Macc 8:17; 3 Macc 4:4), «Pôr diante dos olhos», 1 Cl 5:3. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">ἔχειν</span> (JosAs 7:6; Lucian, Tyrannici. 7; OGI 210, 8; PGiss 67, 10; Just., D. 20, 1 e outros), «Manter algo diante dos olhos», MPol 2:3. <span class=\"greek\">πρὸ</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">εἶναι</span> (Dt 11:18), «Estar diante dos olhos de alguém», 1 Cl 2:1; 39:3 (Job 4:16).—B. 225. DELG s.v. <span class=\"greek\">ὄπωπα</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφθείς, ὀφθήσομαι</h1><div class=\"entry-meta\"><span>formas verbais</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφθείς</span>, <span class=\"greek\">ὀφθήσομαι</span>: ver <span class=\"greek\">ὁράω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄφις, εως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄφις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores; SIG 1168, 113, acerca da serpente empregada nas curas no templo de Asclépio em Epidauro; PGM 8, 11; 13, 261; 881; LXX; pseudoepígrafos, Philo; Jos., Bell. 5, 108, Ant. 1, 41; 2, 287; Just.; Ath. 1, 1), «cobra, serpente».<br>\n① Réptil desprovido de membros, cobra, serpente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:10</a> (ver BHjerl-Hansen, RB 55, ’48, 195–98); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:9</a> (Diod S 5, 58, 4 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὄφεων</span> <span class=\"greek\">διαφθαρῆναι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:19</a> (cf. Achilles Tat. 1, 3, 4 <span class=\"greek\">ὄφεις</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">κόμαι</span>). <span class=\"greek\">ὄφεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκορπίοι</span>, «serpentes e escorpiões» (Procop. Soph., Ep. 136; Sb 6584, 6; Cat. Cod. Astr. VII 177, 21; Dt 8:15; Philo, Praem. 90), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:19</a> (cf. Dt 8:15; Ps 90:13, acerca da proteção contra serpentes). Símbolo de astúcia (cf. Gen 3:1; símbolo de outra espécie em Hyperides, Fgm. 80), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:16</a>; IPol 2:2. Sobre a serpente de bronze no deserto (Num 21:6–9; Wsd 16:5f): <span class=\"greek\">χαλκοῦς</span> <span class=\"greek\">ὀφ</span>. (Num 21:9; cf. 4 Km 18:4; Just., D. 94, 3), 12:6. Essa serpente, levantada, como tipo de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:14</a>; 12:5–7 (uma avaliação tipológica de Num 21:6–9 também em Philo, Leg. All. 2, 77ff, Agr. 95; Just., D. 91, 4 e outros.—Appian, Mithrid. 77 §335, relata um <span class=\"greek\">χαλκοῦς</span> <span class=\"greek\">ὄφις</span> em memória de Filoctetes; Diod S 2, 9, 5, menciona <span class=\"greek\">ὄφεις</span> <span class=\"greek\">ἀργυροί</span> no templo de Zeus na Babilônia).<br>\n② Pessoa percebida como perigosa, serpente, extensão figurada da acepção 1 (cf. SibOr 5:29, sobre Nero): <span class=\"greek\">ὄφεις</span> <span class=\"greek\">γεννήματα</span> <span class=\"greek\">ἐχιδνῶν</span>, «Serpentes, raça de víboras!», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:33</a>.<br>\n③ Figura simbólica frequente na mitologia, serpente (Apollon. Rhod. 4, 128, a serpente que guarda o velocino de ouro; 4, 1434, a Hidra de Lerna; PGM 4, 1638, o deus-sol como <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">ὄφις</span>.—WGrafBaudissin, Studien zur semitischen Religionsgesch. I 1876, 257ff, RE V 1898, 3ff; XVII 1906, 580ff; HGunkel, Schöpfung u. Chaos 1895, 29ff; 320ff; JFrazer, The Golden Bough3 IV 1, 1919, 80ff; Pauly-W. 2.ª série II/1, 508f; EKüster, D. Schlange in der griech. Kunst u. Religion 1913; EUl-back, The Serpent in Myth and Scripture: BS 90, ’33, 449–55), como designação do diabo (ver <span class=\"greek\">δράκων</span>), serpente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:14f</a>; Dg 12:3, 6, 8 (aqui, no v. 6, a serpente do Paraíso é claramente o diabo; Did., Gen. 96, 18). <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄφ</span>. … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐμίανεν</span> <span class=\"greek\">αὐτήν</span>, «O diabo veio e contaminou (Eva)», GJs 13:1. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄφεως</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἔχουσιν</span>, «Eles (os gnósticos) professam a fé de uma serpente», AcPlCor 2:20. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄφ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀρχαῖος</span> (ver <span class=\"greek\">ἀρχαῖος</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:9</a>; 20:2. Ao falar da serpente que seduziu Eva, Paulo evidentemente tem o diabo em mente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:3</a> (Just., A I, 28, 1 e outros; cf. 4 Macc 18:8; ApcMos 17.—Ltzm. e Windisch sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:3</a>; Dibelius, Geisterwelt 50f; SReinach, La Femme et la Serpent: L’Anthropologie 35, 1905, 178ff).—B. 194. BHHW III 1699–1701. Kl. Pauly VI 12–17. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφλισκάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφλισκάνω</span> (Aeschyl., Hdt. e outros; inscrições, papiros, Just.), com o 1.º aoristo raro e tardio <span class=\"greek\">ὤφλησα</span> (Lysias 13, 65, manuscritos, Schwyzer I 709, 746, 752; Hippocr., Ep. 27, ed. Littré; IX p. 426; Ael. Aristid. [ver abaixo]; Just.), incorrer em responsabilidade, tornar-se devedor (com maior ênfase, em comparação com <span class=\"greek\">ὀφέλλω</span>, nas implicações negativas do endividamento); com acusativo, incorrer numa acusação de, tornar-se culpado de alguma coisa (Soph., Oed. R. 512 <span class=\"greek\">κακίαν</span>; Eur., Heracl. 985 <span class=\"greek\">δειλίαν</span>, Ion 443 <span class=\"greek\">ἀνομίαν</span>; Ael. Aristid. 39 p. 732 D.: <span class=\"greek\">αἰσχύνην</span> <span class=\"greek\">ὀφλῆσαι</span>; Philo, Agr. 93 <span class=\"greek\">γέλωτα</span> <span class=\"greek\">ὀφ</span>. = ser objeto de riso): <span class=\"greek\">συμφέρει</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὀφλῆσαι</span> <span class=\"greek\">μεγίστην</span> <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μή</span>, «É melhor para nós incorrer no maior pecado diante de Deus do que...», GPt 11:48.—DELG s.v. <span class=\"greek\">ὀφείλω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀφρῦς</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀφρῦς</span> (sobre a acentuação, ver Mlt-H. 141f), <span class=\"greek\">ύος</span>, <span class=\"greek\">ἡ</span>, literalmente «sobrancelha» (assim em Hom. e outros; PPetr I, 11, 17 [220 a.C.]; PFay 107, 15; BASP XXXII p. 129 ln. 7 [PBer inv. 25576: II d.C.]; Lev 14:9; EpArist 98; Philo); depois, testa, borda de um penhasco ou colina (Il. 20, 151; Polyb. 7, 6, 3; Diod S 22, 13, 4; Plut., Numa 67 [10, 8]; Strabo 5, 3, 7; PAmh 68, 9; 34 [I d.C.]): <span class=\"greek\">ἤγαγον</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">ὀφρύος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄρους</span>, «Levaram-no até a borda do monte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:29</a>. Sobre as circunstâncias, ver MBrückner, PJ 7, 1911, 82.—B. 219. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀχετός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀχετός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (em vários sentidos, Pind. e outros; Sym.), «canal, curso de água» (Hdt. e posteriores; inscrições, papiros; ApcSed 14:3 p. 136, 1 Ja. <span class=\"greek\">ἐν</span> <span class=\"greek\">δάκρυσιν</span> <span class=\"greek\">ὀχετοῦ</span>; Philo, Leg. All. 1, 13, Poster. Cai. 50); depois, dreno, esgoto (Antonin, Liberal. 24, 3; Herodian 5, 8, 9; 7, 7, 3; Acta S. Apollonii §21a Klette); assim em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:19</a> D (em lugar de <span class=\"greek\">ἀφεδρῶνα</span> [ver este verbete]). A acepção «canal intestinal» (atestada desde Hippocr.; X., Mem. 1, 4, 6) não se aplica aqui, devido à proximidade de <span class=\"greek\">κοιλία</span>.—DELG s.v. <span class=\"greek\">ὀχέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀχλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀχλέω</span> (<span class=\"greek\">ὄχλος</span>; Aeschyl., Hdt. e outros; inscrições, papiros, óstracos, LXX; ApcrEzk P 1 verso, 11, restaurado, Denis p. 126), causar incômodo mediante importunação, perturbar, afligir (assim, na maioria das vezes); na passiva (TestSol L; Jos., Ant. 6, 217, Vi. 275 [<span class=\"greek\">ὀχ</span>. <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>]): <span class=\"greek\">ὀχλούμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνευμάτων</span> <span class=\"greek\">ἀκαθάρτων</span>, «Atormentado por espíritos imundos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:16</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:18</a>, variante textual (Tob 6:8 BA <span class=\"greek\">ἐάν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ὀχλῇ</span> <span class=\"greek\">δαιμόνιον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">πονηρόν</span>; AcThom 12 [Aa II/2, 117, 8] <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">δαιμονίων</span> <span class=\"greek\">ὀχλούμενοι</span>).—DELG s.v. <span class=\"greek\">ὄχλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀχλοποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀχλοποιέω</span> (<span class=\"greek\">ὄχλος</span>, <span class=\"greek\">ποιέω</span>), particípio do 1.º aoristo <span class=\"greek\">ὀχλοποιήσας</span> (não encontrado em outro lugar. Mas cf. Hippocr., Mul. 1, 14, ed. Littré; VIII p. 52 <span class=\"greek\">ὄχλον</span> <span class=\"greek\">ποιέει</span>), formar uma turba, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:5</a>.—Ver DELG s.v. <span class=\"greek\">ὄχλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄχλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄχλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Pind., Hdt. e posteriores; inscrições, papiros, LXX; TestJob 24:10; TestJud 7:1; ApcrEzk [Epiph. 70, 8]; EpArist, Philo, Joseph.; Ath. 1, 4; sobre a relação entre <span class=\"greek\">ὄχλος</span> e <span class=\"greek\">ὀχλέω</span>, ver MMeier-Brüjger, Glotta 71, ’93, 28 [ideia básica: um «amontoado» que requer um «montão» de trabalhadores; mas ver DELG e Frisk s.v. <span class=\"greek\">ὄχλος</span>]; empréstimo no hebraico rabínico.—No NT, somente nos Evangelhos [em Marcos, mais frequentemente no singular do que em Mateus e Lucas; ver RBorger, TRu 52, ’87, 28], em Atos e no Apocalipse).<br>\n① Número relativamente grande de pessoas reunidas, multidão.<br>\nⓐ Reunião ocasional de grande número de pessoas, sem referência a categoria social, multidão, aglomeração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:23</a>, 25; 15:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:4</a> (ver DDaube, ET 50, ’38, 138f); 3:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:13</a>; 6:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:14</a>; 21:34f e frequentemente; AcPl Ha 5, 11. <span class=\"greek\">τὶς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span>, «Alguém da multidão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:13</a>; cf. 11:27. <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:38</a>. <span class=\"greek\">τινὲς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Φαρισαίων</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span>, «Alguns dos fariseus que estavam na multidão», 19:39. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span>, «Afastado da multidão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:17</a>, 33. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἠδύνατο</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span>, «Ele não conseguia, por causa da multidão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:3</a> (ver <span class=\"greek\">ἀπό</span> 5a). <span class=\"greek\">οὐ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ὄχλου</span>, «Sem uma multidão (presente)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:18</a> (cf. v. 12). Isto equivale em significado a <span class=\"greek\">ἄτερ</span> <span class=\"greek\">ὄχλου</span> (ver <span class=\"greek\">ἄτερ</span>), «Quando não havia multidão presente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:6</a> (ver WLarfeld, Die ntl. Evangelien nach ihrer Eigenart 1925, 190), a menos que <span class=\"greek\">ὄχ</span>. signifique aqui «tumulto» (Hdt. e posteriores; assim Goodsp.). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεάτρῳ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span>, AcPl Ha 1, 24.—<span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄχλος</span> (Aelian, VH 2, 6), «Toda a multidão, todo o povo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:2b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:13</a>; 4:1b; 9:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:27</a>; MPol 9:2; 16:1. Também <span class=\"greek\">ὅλος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄχλος</span>, AcPl Ha 4, 35.—<span class=\"greek\">πολὺς</span> <span class=\"greek\">ὄχ</span>. (Jos., Vi. 133; 277), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:34</a>. <span class=\"greek\">ὄχ</span>. <span class=\"greek\">πολύς</span> (Cebes 1, 2; IG IV2/1, 123, 25; várias vezes na LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:21</a>, 24; 9:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:2</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πολὺς</span> <span class=\"greek\">ὄχ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:37</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄχ</span>. <span class=\"greek\">πολύς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:9</a>, 12.—<span class=\"greek\">ὄχ</span>. <span class=\"greek\">ἱκανός</span>, «Multidão considerável», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:24</a>, 26; cf. 19:26. <span class=\"greek\">ὄχ</span>. <span class=\"greek\">τοσοῦτος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:33</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πλεῖστος</span> <span class=\"greek\">ὄχ</span>., «A grande multidão» ou «a maior parte da multidão», 21:8 (verbo no plural com substantivo coletivo, como em Memnon [I a.C./I d.C.]: 434 Fgm. 1, 28, 6 Jac. <span class=\"greek\">εἷλον</span> … <span class=\"greek\">ἡ</span> <span class=\"greek\">Ῥωμαίων</span> <span class=\"greek\">δύναμις</span>. Cf. B-D-F §134, 1). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:1a</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχ</span>., «A maior parte da multidão», Hs 8, 1, 16; <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχ</span>., 9, 4, 4; <span class=\"greek\">αἱ</span> <span class=\"greek\">μυριάδες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχ</span>., «A multidão aos milhares e milhares», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:1</a>.—O plural é comum em Mateus, Lucas e Atos (conforme o uso posterior: X., Mem. 3, 7, 5; Dionys. Hal.; Ael. Aristid. 34, 47 K.=50 p. 564 D.; Jos., Ant. 6, 25 e outros, Schwyzer II 43; cf. Mussies 71 e 85): <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄχλοι</span>, «As multidões, o povo» (este último sentido claramente em Posidon.: 87 Fgm. 36, 51 Jac. <span class=\"greek\">συλλαλήσαντες</span> <span class=\"greek\">αὑτοῖς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄχ</span>.; Diod S 1, 36, 10; 1, 83, 8 <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὄχλων</span> <span class=\"greek\">ψυχαῖς</span>; 1, 72, 5 <span class=\"greek\">μυριάδες</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὄχλων</span>; 4, 42, 3; 14, 7, 2 <span class=\"greek\">ὄχλων</span> <span class=\"greek\">πλῆθος</span> = multidão de pessoas; 36, 15, 2 <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">ὄχλοι</span> = o povo da cidade; Artem. 1, 51 p. 59, 13 Pack; Vi. Aesopi G 124 P; Ps.-Aeschines, Ep. 10, 4 <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἅμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἄλλοις</span> <span class=\"greek\">ὄχλοις</span>; Ps.-Demetr., Form. Ep. p. 7, 11; OGI 383, 151 [I a.C.]; Jos., Ant. 9, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:1</a>; 7:28; 9:8, 33, 36 e frequentemente; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:7</a>, 10; 4:42; 5:3; 8:42, 45 e frequentemente; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:6</a>; 13:45; 14:11, 13, 18f; 17:13. Em Marcos, apenas 6:33, variante textual; em João, apenas 7:12a (variante textual <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄχλῳ</span>). MPol 13:1. Sem artigo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:1</a> (sobre a questão textual, RBorger, TRu 52, ’87, 28); <span class=\"greek\">ὄχ</span>. <span class=\"greek\">πολλοί</span> (ver <span class=\"greek\">πολύς</span> 2a<span class=\"greek\">α</span><span class=\"hebrew\" dir=\"rtl\">ב</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:25</a>; 8:1; 12:15; 13:2a; 15:30; 19:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:15</a>; 14:25. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄχ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:23</a>.—Um paralelo linguístico ao plural <span class=\"greek\">ὄχλοι</span> e um paralelo ao tipo de manobra política de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:15</a> (<span class=\"greek\">ὁ</span> <span class=\"greek\">Πιλᾶτος</span> <span class=\"greek\">βουλόμενος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄχλῳ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱκανὸν</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">ἀπέλυσεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Βαραββᾶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">φραγελλώσας</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">σταυρωθῇ</span>) é fornecido por PFlor 61, 59ff [85 d.C.], no qual, segundo a ata judicial, G. Septimius Vegetus diz a certo Phibion: <span class=\"greek\">ἄξιος</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἦς</span> <span class=\"greek\">μαστιγωθῆναι</span> … <span class=\"greek\">χαρίζομαι</span> <span class=\"greek\">δέ</span> <span class=\"greek\">σε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὄχλοις</span> (ver Dssm., LO 229 [LAE 266f] e, sobre o favor dos <span class=\"greek\">ὄχλοι</span>, PGM 36, 275).<br>\nⓑ Reunião de pessoas que apresenta alguma característica ou condição distintiva.<br>\n<span class=\"greek\">α</span>. Número elevado de pessoas de condição social relativamente baixa, o povo comum, a população (PJoüon, RSR 27, ’37, 618f), em contraste com os governantes: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:5</a>; 15:10; 21:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:18</a>, 32 (variante textual <span class=\"greek\">λαόν</span>, ver este verbete, 2); 12:12. Analogamente, o plural <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄχ</span>. (EpArist 271), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:46</a>. As classes inferiores (X., Cyr. 2, 2, 21, Hier. 2, 3 e outros); <span class=\"greek\">ἐπίστασις</span> <span class=\"greek\">ὄχλου</span>, «Tumulto entre o povo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:12</a>. Em sentido depreciativo, ralé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:49</a> (Bultmann ad loc. [com bibliografia]).<br>\n<span class=\"greek\">β</span>. Grupo ou companhia de pessoas com interesses comuns ou condição distintiva, grande número (grupo, multidão), com genitivo (Eur., Iph. A. 191 <span class=\"greek\">ἵππων</span> e outros; Jos., Ant. 3, 66; Ath, 1, 4 <span class=\"greek\">ὄχλον</span> <span class=\"greek\">ἐγκλημάτων</span>): <span class=\"greek\">ὄχ</span>. <span class=\"greek\">τελωνῶν</span>, «Multidão de cobradores de impostos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:29</a>. <span class=\"greek\">ὄχ</span>. <span class=\"greek\">μαθητῶν</span>, 6:17. <span class=\"greek\">ὄχ</span>. <span class=\"greek\">ὀνομάτων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:15</a>. <span class=\"greek\">ὄχ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱερέων</span>, 6:7.<br>\n② Grande massa de pessoas, sem referência à condição social nem às circunstâncias de sua formação, horda, massa; plural <span class=\"greek\">ὄχλοι</span> como sinônimo ao lado de <span class=\"greek\">λαοί</span> e <span class=\"greek\">ἔθνη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:15</a> (cf. Da 3:4).—VHunter, Thucydides and the Sociology of the Crowd: ClJ 84, ’88, 17–30, especialmente 17, nota 5 (bibliografia sobre o estudo de multidões); WCarter, CBQ 55, ’93, 56, nota 9 (bibliografia sobre a perspectiva sociológica).—B. 929. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ὀχοζίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ὀχοζίας</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\" dir=\"rtl\">אֲחַזְיָה</span>), Acazias, rei hebreu (4 Km 8:24; 9:16; 2 Ch 22:1; AscIs 2:13–16 = MartIs, Denis p. 111 ln. 9, 13, 19, 25 [rei de Gomorra]; Joseph.), na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:8</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:23ff</a> D.—BHHW I 50.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀχυρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀχυρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Hes. e outros; LXX; PsSol 2:1; Jos., Ant. 11, 89; TestJud 9:4; <span class=\"greek\">πόλεις</span> <span class=\"greek\">ὀχ</span>. Theoph. Ant. 3, 20 [p. 244, 6]), relativo a firmeza ou estabilidade, forte, firme, sólido: <span class=\"greek\">μακροθυμία</span>, Hm 5, 2, 3.—Acerca de firme adesão a uma opinião: <span class=\"greek\">τινὲς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐλάλησεν</span> <span class=\"greek\">ὀχυροὶ</span> <span class=\"greek\">λέγοντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:15</a>, variante textual. Ver o próximo verbete.—DELG s.v. <span class=\"greek\">ἐχυρός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀχύρωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀχύρωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὀχυρόω</span>, «fortificar»; em diversos sentidos, «fortaleza, fortificação, prisão», desde X., Hell. 3, 2, 3; SIG 502, 39 [III a.C.]; OGI 455, 14 [39 d.C.]; PPetr II, 13 [3], 2 [III a.C.]; PStras 85, 23; LXX; Jos., Ant. 13, 27), instalação militar resistente, fortaleza, em sentido figurado (Hybreas [I a.C.] em Seneca Rhet., Suas. 4, 5; Pr 21:22 <span class=\"greek\">καθεῖλεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀχύρωμα</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐπεποίθεισαν</span>; 10:29 <span class=\"greek\">ὀχύρωμα</span> <span class=\"greek\">ὁσίου</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">κυρίου</span>) acerca das armas espirituais, que são <span class=\"greek\">δυνατὰ</span> … <span class=\"greek\">πρὸς</span> <span class=\"greek\">καθαίρεσιν</span> <span class=\"greek\">ὀχυρωμάτων</span>, «Poderosas para destruir fortalezas», isto é, para destruir <span class=\"greek\">λογισμοί</span>, sofismas, e tudo aquilo que se opõe à <span class=\"greek\">γνῶσις</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a> (cf. Philo, Conf. Lingu. 129; 130 <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀχ</span>. <span class=\"greek\">τούτου</span> <span class=\"greek\">καθαίρεσιν</span>).—DELG s.v. <span class=\"greek\">ἐχυρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀψάριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀψάριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span>, diminutivo de <span class=\"greek\">ὄψον</span> (Hom. e outros; Tob 2:2 BA; 7:8 BA) = «comida cozida», consumida com pão. <span class=\"greek\">ὀψάριον</span> também apresenta esse sentido (PRyl 229, 21; ver abaixo). Como alimento comido com pão, <span class=\"greek\">ὀψάριον</span> pode significar «petisco», em geral (assim em Tob 2:2 S; Plut., Mor. 126a; Philemo Com. Fgm. 98, 5 K.; POxy 531, 18; PFay 119, 31), ou especificamente «peixe» (cf. Num 11:22 <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄψος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>; Iambl., Vi. Pyth. 21, 98 <span class=\"greek\">θαλασσίων</span> <span class=\"greek\">ὄψων</span>.—Suda: <span class=\"greek\">ὀψάριον</span>· <span class=\"greek\">τὸ</span> <span class=\"greek\">ἰχθύδιον</span>. Esse sentido de <span class=\"greek\">ὀψάριον</span> aparece em diversos autores cômicos citados em Athen. 9, 35 p. 385f; Lucian, Jupp. Conf. 4; Cyranides p. 109, 4; 5; GDI 4706, 191 [Thera]; OGI 484, 12; 16; BGU 1095, 16 [57 d.C.] <span class=\"greek\">λαγύνιον</span> <span class=\"greek\">ταριχηροῦ</span> [=<span class=\"greek\">ῶν</span>] <span class=\"greek\">ὀψαρίων</span> = peixe conservado; PLond II, 483, 77 p. 328 [616 d.C.] <span class=\"greek\">ὀψάρια</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παντοίων</span> <span class=\"greek\">ὑδάτων</span>. No grego moderno, <span class=\"greek\">ψάρι</span> = peixe). Em nossa literatura, na qual ocorre apenas em João, tem este último sentido: <span class=\"greek\">δύο</span> <span class=\"greek\">ὀψάρια</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:9</a> (os paralelos sinóticos têm <span class=\"greek\">δύο</span> <span class=\"greek\">ἰχθύας</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:17</a>, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:38</a>, 41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:13</a>, 16. Cf. PRyl 229, 21 [38 d.C.] <span class=\"greek\">τ</span>. <span class=\"greek\">ἄρτους</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀψάριον</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:11</a>; 21:9f, 13.—JKalitsunakis, <span class=\"greek\">Ὄψον</span> und <span class=\"greek\">ὀψάριον</span>: PKretschmer Festschr 1926, 96–106; em oposição, ADebrunner, IndogF 24, 1927, 336–43; ver ainda JKalitsunakis, Philol. Wochenschrift 1928, 1357f; M-EBoismard, RB 54, ’47, 478, nota 2; APitta, Biblica 71, ’90, 348–64.—Ver também B. 184. New Docs 2, 92. DELG s.v. <span class=\"greek\">ὄψον</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀψέ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀψέ</span>, advérbio (Hom. e outros; inscrições, papiros, LXX; En, TestSol, TestAbr A 6 p. 83, 19 e 22 [Stone p. 14]; SibOr 5, 51; Philo, Joseph.; Just., D. 52, 4).<br>\n① Relativo a um momento avançado do dia (geralmente entre o pôr do sol e a escuridão), tarde, com genitivo: <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span>, «Numa hora tardia» (Demosth. 21, 84; Chariton 1, 14, 5; UPZ 6, 15 [163 a.C.]; Jos., Ant. 16, 218), MPol 7:1.<br>\n② Referente especificamente ao período entre o fim da tarde e a escuridão, tarde no dia, entardecer, isto é, à tarde, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:35</a>. <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">οὔσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span> (ver B-D-F §129), 11:11, variante textual (em lugar de <span class=\"greek\">ὀψίας</span>). Como predicativo (B-D-F §434, 1; ver também Rob. 973): <span class=\"greek\">ὅταν</span> <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">ἐγένετο</span>, «Quando chegou a tarde, quando anoiteceu», 11:19.—Empregado quase como substantivo indeclinável (Thu. 3, 108, 3 e outros <span class=\"greek\">ἐς</span> <span class=\"greek\">ὀψέ</span>): <span class=\"greek\">μέχρις</span> <span class=\"greek\">ὀψέ</span>, «Até a tarde», Hs 9, 11, 1; também <span class=\"greek\">ἕως</span> <span class=\"greek\">ὀψέ</span> (PLond III, 1177, 66 p. 183 [113 d.C.]), 9, 11, 2.—TMartin, BR 38, ’93, 55–69.<br>\n③ Marcador de um momento posterior a outro momento, depois de, com referência especial ao atraso; funciona como preposição com genitivo: <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">σαββάτων</span>, «Depois do sábado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:1</a> (Aelian, VH 2, 23; Polyaenus 5, 2, 5 <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span> = mais tarde do que a hora [determinada]; Philostrat., Vi. Apoll. 4, 18, 138, 8 <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">μυστηρίων</span>; 6, 10, 213, 24 <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">τούτων</span>, Her 12, 190, 10 <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μάχης</span>.—B-D-F §164, 4; Rob. 645f; ETobac, RHE 20, 1924, 239–43; JMaiworm, ThGl 27, ’35, 210–16; Goodsp., Probs. 43–45; JGrintz, JBL 79, ’60, 32–47).—B. 961. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀψία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀψία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>: ver <span class=\"greek\">ὄψιος</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0263-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄψιμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄψιμος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὀψέ</span>; Hom. e outros; papiros, LXX; como nome próprio, Ath. 6, 1), primariamente relativo a um período relativamente tardio (Il. 2, 325), especialmente em conexão com atividades agrícolas (ver L-S-J-M s.v.); em nossa literatura, diz-se da chuva que chega na primavera (março a abril), depois de passarem as chuvas normais de inverno (<span class=\"hebrew\" dir=\"rtl\">מַלְקוֹשׁ</span> Dt 11:14; ver Dalman, Arbeit I 122ff; 302 ff e outros): <span class=\"greek\">ὑετὸς</span> <span class=\"greek\">ὄψιμος</span> (com <span class=\"greek\">πρόϊμος</span>, como em Dt 11:14; Jer 5:24 e outros), chuva tardia, chuva da primavera, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7</a>, variante textual em lugar do substantivo (<span class=\"greek\">ὁ</span>) <span class=\"greek\">ὄψιμος</span>, na mesma acepção. Ver <span class=\"greek\">πρόϊμος</span>.—DELG s.v. <span class=\"greek\">ὀψέ</span>. M-M.</p></section></article>"};
